mapper.select:
SELECT j.job_id, j.job_code, j.trigger_type, j.operator_id, j.status, j.file_path, j.file_size, j.message, j.started_at, j.finished_at, j.create_time, u.username AS operator_name FROM sign_backup_job j LEFT JOIN sys_user u ON j.operator_id = u.id
AND j.trigger_type = #{triggerType} AND j.status = #{status}
ORDER BY j.create_time DESC

